<?php
require_once __DIR__ . '/../bootstrap.php';require_once __DIR__.'/../gmb/_google.php';
$secret=(string)envv('CRON_SECRET','');$provided=(string)($_GET['key']??($_SERVER['HTTP_X_CRON_SECRET']??''));if($secret===''||!hash_equals($secret,$provided))json_response(['ok'=>false,'error'=>'Unauthorized'],401);
$q=db()->query("SELECT j.*,c.account_id,c.location_id FROM gmb_content_jobs j JOIN gmb_connections c ON c.business_id=j.business_id AND c.is_enabled=1 WHERE j.status='scheduled' AND j.scheduled_at<=NOW() ORDER BY j.scheduled_at ASC LIMIT 20");$jobs=$q->fetchAll();$done=[];
foreach($jobs as $j){$id=(int)$j['id'];try{db()->prepare("UPDATE gmb_content_jobs SET status='processing' WHERE id=?")->execute([$id]);$p=json_decode((string)$j['payload_json'],true)?:[];$body=['languageCode'=>'en-US','summary'=>(string)($p['summary']??''),'topicType'=>'STANDARD'];if(!empty($p['cta_url']))$body['callToAction']=['actionType'=>'LEARN_MORE','url'=>$p['cta_url']];if(!empty($p['image_url']))$body['media']=[['mediaFormat'=>'PHOTO','sourceUrl'=>$p['image_url']]];$a=preg_replace('/[^0-9]/','',(string)$j['account_id']);$l=preg_replace('/[^0-9]/','',(string)$j['location_id']);gbp_request('POST',"https://mybusiness.googleapis.com/v4/accounts/{$a}/locations/{$l}/localPosts",$body);db()->prepare("UPDATE gmb_content_jobs SET status='published',published_at=NOW(),error_message=NULL WHERE id=?")->execute([$id]);$done[]=['id'=>$id,'status'=>'published'];}catch(Throwable $e){db()->prepare("UPDATE gmb_content_jobs SET status='failed',error_message=? WHERE id=?")->execute([$e->getMessage(),$id]);$done[]=['id'=>$id,'status'=>'failed','error'=>$e->getMessage()];}}
json_response(['ok'=>true,'processed'=>$done]);
